function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87ceeb", 255); // Sky blue
  brush.beginShape();
  brush.vertex(0, 0); // Top left
  brush.vertex(400, 0); // Top right
  brush.vertex(200, 400); // Bottom center
  brush.endShape(true);

  // Green hills
  brush.fill("#98fb98", 255); // Green
  brush.beginShape();
  brush.vertex(0, 300); // Top left hill
  brush.vertex(400, 300); // Top right hill
  brush.vertex(200, 400); // Bottom center hill
  brush.endShape(true);

  // Sun
  brush.fill("#ffcc00", 255); // Yellow
  brush.beginShape();
  brush.vertex(100, 50); // Top left sun
  brush.vertex(300, 50); // Top right sun
  brush.vertex(200, 20); // Bottom center sun
  brush.endShape(true);
}
```

